const token=env.get('SC_SCALE_TOKEN');
if(!token||token.length<32){node.status({fill:'red',shape:'ring',text:'SC_SCALE_TOKEN belum diisi'});return null;}
node.status({});msg.headers={'X-Scale-Token':token};msg.payload='';return msg;

if(msg.statusCode!==200||msg.payload?.status!=='success'||!Array.isArray(msg.payload.data)){node.status({fill:'red',shape:'ring',text:'Backend sesi belum siap'});return null;}
node.status({fill:'green',shape:'dot',text:'Bridge aktif'});
const commands=msg.payload.data.map(s=>({topic:'smartcattle/scales/'+s.device_id+'/command',qos:'1',retain:false,payload:JSON.stringify({...s,command:'arm',unit:'kg'})}));
return [commands];

if(msg.retain===true)return null;
try{
 const token=env.get('SC_SCALE_TOKEN');if(!token||token.length<32)throw Error('SC_SCALE_TOKEN belum diisi');
 const device=String(msg.topic).split('/')[2];
 if(!['scale-weight-01','scale-feed-01'].includes(device))throw Error('Perangkat tidak dikenal');
 let b=msg.payload;if(Buffer.isBuffer(b))b=b.toString('utf8');if(typeof b==='string')b=JSON.parse(b);
 if(!b||typeof b!=='object'||Array.isArray(b)||b.device_id!==device||!/^([a-f0-9]{32})$/.test(b.session_id))throw Error('Identitas tidak cocok');
 if(b.stable!==true||b.unit!=='kg'||typeof b.weight_kg!=='number'||!Number.isFinite(b.weight_kg))throw Error('Hasil belum valid/stabil');
 msg._scaleDevice=device;msg._scaleSession=b.session_id;
 msg.headers={'X-Scale-Token':token,'Content-Type':'application/json'};
 msg.payload=JSON.stringify(b);return msg;
}catch(e){node.warn(e.message);return null;}

if(!msg._scaleDevice)return null;
const ok=msg.statusCode===200&&msg.payload?.status==='success';
const retryable=!Number.isInteger(msg.statusCode)||msg.statusCode>=500;
return {topic:'smartcattle/scales/'+msg._scaleDevice+'/ack',qos:'1',retain:false,payload:JSON.stringify({session_id:msg._scaleSession,status:ok?'saved':retryable?'retry':'rejected',duplicate:!!msg.payload?.duplicate,message:ok?'Tersimpan':String(msg.payload?.message||'Bridge belum merespons')})};
